            372 => 
            array (
                'id' => 1711,
                'lang_code' => 'en',
            'name' => 'Electronic Document and Records Management (EDRM)',
                'description' => '<p>This course is designed to equip professionals with the skills and knowledge required to successfully implement, manage, and maintain an effective EDRM system.<br /><br />This 5-day course will cover essential principles, best practices, and emerging trends in EDRM, ensuring participants are well-equipped to handle the challenges of electronic document and records management in today\'s rapidly evolving digital landscape. Join us as we explore the intricacies of EDRM, from information governance and legal requirements to cutting-edge technologies and future trends.</p>',
                'duration' => '5',
            'days_content' => '["<p><strong>Introduction to Electronic Document and Records Management (EDRM)<br /><br /></strong></p>\\n<p>Overview of EDRM and its importance</p>\\n<p>Differences between documents and records</p>\\n<p>The role of EDRM in information governance</p>\\n<p>Legal and regulatory requirements</p>\\n<p>EDRM models and standards</p>","<p><strong>Electronic Document Management<br /><br /></strong></p>\\n<ul>\\n<li>Creating and capturing electronic documents</li>\\n<li>Document metadata, tagging, and taxonomy</li>\\n<li>Document version control and collaboration</li>\\n<li>Document search and retrieval</li>\\n<li>Security and access control</li>\\n</ul>\\n<p>&nbsp;</p>","<p><strong>Electronic Records Management<br /><br /></strong></p>\\n<ul>\\n<li>The lifecycle of electronic records</li>\\n<li>Retention and disposition schedules</li>\\n<li>Legal holds and preservation of records</li>\\n<li>Records classification and indexing</li>\\n<li>Auditing and monitoring records</li>\\n</ul>\\n<p>&nbsp;</p>","<p><strong>Implementing an EDRM System<br /><br /></strong></p>\\n<ul>\\n<li>Assessing organizational needs and requirements</li>\\n<li>Choosing the right EDRM solution</li>\\n<li>Planning and executing the implementation process</li>\\n<li>Training staff and promoting user adoption</li>\\n<li>Developing a maintenance and support plan</li>\\n</ul>\\n<p>&nbsp;</p>","<p><strong>EDRM Best Practices and Future Trends<br /><br /></strong></p>\\n<ul>\\n<li>EDRM best practices for security, compliance, and efficiency</li>\\n<li>Cloud-based EDRM solutions and their benefits</li>\\n<li>Integrating EDRM with other information management systems</li>\\n<li>AI and machine learning in EDRM</li>\\n<li>Course summary and action plan for the workplace</li>\\n</ul>"]',
                'related_courses' => '[534,554,810]',
                'category_id' => 6,
                'online' => 1,
                'created_at' => '2025-04-03 12:50:37',
                'updated_at' => '2025-04-03 12:50:37',
            ),
