            311 => 
            array (
                'id' => 2157,
                'lang_code' => 'en',
                'name' => 'Public Policy Challenges of the 21st Century',
                'description' => NULL,
                'duration' => '5',
                'days_content' => NULL,
                'related_courses' => NULL,
                'category_id' => 55,
